<script>
const rowsEl=document.getElementById('rows');
const exprEl=document.getElementById('expression');
const warningEl=document.getElementById('warning');
let expr='', previousAnswer=null, committed=[];

function render(s){
  if(!s)return '';
  let t=s;
  t=t.replace(/sqrt\(([^)]*)\)/g,'<span class="radical">√<span style="font-size:.8em">$1</span></span>');
  t=t.replace(/abs\(([^)]*)\)/g,'|$1|');
  t=t.replace(/(\d+)\^(\d+)/g,'$1<span class="sup">$2</span>');
  t=t.replace(/(\d+)\s*\/\s*(\d+)/g,'<span class="frac"><span class="top">$1</span><span class="bottom">$2</span></span>');
  t=t.replace(/\*/g,' × ').replace(/\+/g,' + ').replace(/-/g,' − ').replace(/\//g,' ÷ ');
  return t;
}
function clean(s){return s.replace(/\s/g,'')}
function evaluate(s){
  let x=clean(s).replace(/sqrt\(([^()]*)\)/g,'Math.sqrt($1)').replace(/abs\(([^()]*)\)/g,'Math.abs($1)').replace(/\^/g,'**');
  if(!/^[0-9+\-*/().%**Mathsqrtabs]+$/.test(x)) return null;
  try{let v=Function('"use strict";return ('+x+')')();return Number.isFinite(v)?v:null}catch(e){return null}
}
function draw(){
  exprEl.innerHTML=render(expr);
  warningEl.textContent=(expr && evaluate(expr)===null)?'⚠':'';
}
function commit(){
  if(!expr)return;
  let val=evaluate(expr);
  if(val===null){draw();return}
  committed.push({e:expr,a:val});
  previousAnswer=val;
  expr='';
  rowsEl.innerHTML=committed.map(r=>`<div class="row"><span>${render(r.e)}</span><span class="answer">= ${r.a}</span></div>`).join('');
  draw();
}
function add(v){expr+=v;draw()}
document.querySelectorAll('[data-key]').forEach(b=>b.addEventListener('click',()=>add(b.dataset.key)));
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{
  let a=b.dataset.action;
  if(a==='enter')commit();
  else if(a==='delete')expr=expr.slice(0,-1);
  else if(a==='back')expr=expr.slice(0,-1);
  else if(a==='square')expr+='^2';
  else if(a==='power')expr+='^';
  else if(a==='sqrt')expr+='sqrt(';
  else if(a==='abs')expr+='abs(';
  else if(a==='fraction')expr+='/';
  draw();
}));
document.addEventListener('keydown',e=>{
  if(/[0-9.+\-*/()%]/.test(e.key)){add(e.key);e.preventDefault()}
  if(e.key==='Enter'){commit();e.preventDefault()}
  if(e.key==='Backspace'){expr=expr.slice(0,-1);draw()}
});
draw();
</script>
